+static int it6625_s_ctrl_audio_sampling_rate(struct v4l2_subdev *sd)
+{
+	struct it6625 *it6625 = sd_to_6625(sd);
+
+	return v4l2_ctrl_s_ctrl(it6625->ctrl_audio_sampling_rate,
+				get_audio_sampling_rate(it6625));
+}
