+static void it6625_enable_stream(struct it6625 *it6625, bool enable)
+{
+	struct v4l2_subdev *sd = &it6625->sd;
+	int val;
+
+	v4l2_dbg(3, debug, sd, "%s: %sable",
+		 __func__, enable ? "en" : "dis");
