+{
+	guard(mutex)(&it6625->it6625_lock);
+	memset(&it6625->timings, 0, sizeof(it6625->timings));
+}
+
+static void it6625_irq_hdmi_5v_change(struct it6625 *it6625)
+{
+	struct v4l2_subdev *sd = &it6625->sd;
