> +static int husb320_set_vbus(struct husb320 *husb, bool enable)
> +{
> +	int ret;
> +
> +	if (!husb->vbus || husb->vbus_on == enable)
> +		return 0;
> +
> +	if (enable)
> +		ret = regulator_enable(husb->vbus);
> +	else
> +		ret = regulator_disable(husb->vbus);
> +	if (ret)
> +		return ret;
> +
> +	husb->vbus_on = enable;
> +
> +	return 0;
> +}
